-- Korean locale additions for `item_template_locale`.
-- Update existing rows and insert missing rows only when the parent exists.
-- Preserve existing Korean text and other locales.
DROP TEMPORARY TABLE IF EXISTS `_koKR_stage_item_template_locale`;
CREATE TEMPORARY TABLE `_koKR_stage_item_template_locale` (
    `ID` INT UNSIGNED NOT NULL,
    `Name` LONGTEXT NULL,
    `Description` LONGTEXT NULL,
    PRIMARY KEY (`ID`)
) ENGINE=InnoDB;



































UPDATE `item_template_locale` AS `l`
INNER JOIN `_koKR_stage_item_template_locale` AS `s` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
INNER JOIN `item_template` AS `p` ON `p`.`entry` = `s`.`ID`
SET `l`.`Name` = IF(`s`.`Name` IS NOT NULL AND (`l`.`Name` IS NULL OR `l`.`Name` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Name`, `l`.`Name`),
    `l`.`Description` = IF(`s`.`Description` IS NOT NULL AND (`l`.`Description` IS NULL OR `l`.`Description` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Description`, `l`.`Description`);

SELECT `s`.`ID`, 'koKR', `s`.`Name`, `s`.`Description`
FROM `_koKR_stage_item_template_locale` AS `s`
INNER JOIN `item_template` AS `p` ON `p`.`entry` = `s`.`ID`
LEFT JOIN `item_template_locale` AS `l` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
WHERE `l`.`ID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_item_template_locale`;
